const value = Number(msg.payload.soil_moisture);
if (!Number.isFinite(value) || value < 0 || value > 100) { return null; }
flow.set('latestMoisture', msg.payload);
msg.measurement = 'soil_moisture';
msg.payload = [{ soil_moisture: value }, { device: msg.payload.device_id || 'unknown', sector: String(msg.payload.sector || 1) }];
return msg;

const fields = msg.payload[0] || {};
const tags = msg.payload[1] || {};
const value = Number(fields.soil_moisture);
if (!Number.isFinite(value)) return null;
const device = String(tags.device || 'unknown').replace(/[, =]/g, '_');
msg.url = 'http://influxdb:8086/api/v2/write?org=smart-irrigation&bucket=telemetry&precision=ms';
msg.headers = { 'Content-Type': 'text/plain', 'Authorization': 'Token irrigation-local-token' };
msg.payload = `soil_moisture,device=${device},sector=${tags.sector || '1'} value=${value} ${Date.now()}`;
return msg;

const moisture = Number(msg.payload.soil_moisture);
const low = Number(flow.get('lowThreshold') ?? 40);
const high = Number(flow.get('highThreshold') ?? 60);
const current = flow.get('desiredPumpState') || 'off';
let desired = current;
if (current === 'off' && moisture < low) desired = 'on';
if (current === 'on' && moisture >= high) desired = 'off';
if (desired === current) return null;
flow.set('desiredPumpState', desired);
msg.headers = { 'content-type': 'application/json' };
msg.payload = { action: desired, mode: flow.get('operatingMode') || 'rule_based', requested_at: new Date().toISOString() };
msg.url = 'http://host.containers.internal:8081/pump';
return msg;
